document.addEventListener('DOMContentLoaded',()=>{
 document.querySelectorAll('.demo-modal-content').forEach((content,i)=>{const d=document.createElement('dialog');d.className='demo-dialog';d.id='alamo-dialog-'+i;const title=content.querySelector('h2');if(title){title.id='alamo-dialog-title-'+i;d.setAttribute('aria-labelledby',title.id)}const parent=content.parentElement;d.append(content);document.body.append(d);const trigger=parent.querySelector('.demo-open-modal a');if(trigger)trigger.addEventListener('click',e=>{e.preventDefault();d.showModal()});content.querySelector('.demo-close-modal a')?.addEventListener('click',e=>{e.preventDefault();d.close();trigger?.focus()});d.addEventListener('close',()=>trigger?.focus());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
 document.querySelectorAll('.demo-form').forEach(f=>{f.addEventListener('submit',e=>{e.preventDefault();f.querySelector('[role=status]').hidden=false;f.querySelector('[role=status]').textContent='Demo complete. Your enquiry has been validated locally; nothing was sent.'});});
});

